{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Proguanil has absolute oral bioavailability as high as 60% and is rapidly and extensively absorbed regardless of food intake; with a very high assay-transfer score, this supports high F for the query under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Thalidomide, despite slow absorption, has estimated oral bioavailability of 80-100% in humans, providing strong transferred evidence for high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "(S)-thalidomide has an absolute oral bioavailability around 80% measured against intravenous infusion, directly supporting classification above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Omapatrilat has an absolute oral bioavailability of 21.9% in control subjects, the lowest transferred value in the set, yet still exceeds the 20% threshold and therefore supports high rather than low.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferred experimental evidence points to oral bioavailability at or above 20%, with several direct absolute-F measurements of 30-100%. The query is atovaquone, a lipophilic naphthoquinone whose absorption is food-enhanced, and the fed-state condition further supports F >= 20%. Confidence is moderate because no direct atovaquone absolute-F measurement is included and solubility-limited absorption remains a possible liability.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for atovaquone in the fed state is present in the evidence set.",
    "Atovaquone's poor aqueous solubility could limit absorption, and the quantitative magnitude of the food effect is not directly evidenced here."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

